package dev.resilience4cata.reactor.generated;

import dev.resilience4cata.generated.Abi;

/**
 * The generated-code level this reactor module supports: a generated class with {@code Mono} or {@code Flux} methods
 * calls {@link #require} first in each of its constructors, after core's {@link Abi#require}, so that code generated
 * by a newer processor fails at once with {@code R4C-RT-021} rather than with a {@code NoSuchMethodError}. The same
 * rule as core's: code generated by processor {@code 1.a} runs on this module {@code 1.b} for every {@code b >= a}.
 */
public final class ReactorAbi {

    /** The highest level this module supports. Not a public constant: it would be inlined into callers. */
    private static final int LEVEL = 2;

    private ReactorAbi() {
    }

    /**
     * Checks that this module runs code of {@code level}.
     *
     * @param level the level of the processor that generated {@code generated}
     * @param generated the generated class
     * @throws IllegalStateException {@code R4C-RT-021} if this module is too old for it
     */
    public static void require(int level, Class<?> generated) {
        if (level > LEVEL) {
            throw Abi.tooOld("resilience4cata-reactor", generated, level, LEVEL);
        }
    }
}
